ShortOption() throws Exception {
        DefaultParser parser = new DefaultParser();
        parser.parse(new Options("-s", "-a"));
        assertThat(parser.getOptions().getRequiredOptions(), is(equalTo(new String[] { "-s", "-a" })));
        assertThat(parser.getOptions().getOptionalOptions(), is(emptyArray()));
        assertThat(parser.getOptions().getPositionalArguments(), is(emptyArray()));
        assertThat(parser.getOptions().getIgnoredOptions(), is(emptyArray()));
        assertThat(parser.getOptions().getUnrecognizedOptions(), is(emptyArray()));
        assertThat(parser.getOptions().getOptionGroup().getSelected(), is(nullValue()));
        assertThat(parser.getOptions().getOptionGroup().isRequired(), is(false));
    }

